def f(n):
    if n == 0: return 0
    m = 0
    while n % 2 == 0:
        m += 1
        n //= 2
    return n

def check(v, max_u=10000):
    for u in range(1, max_u):
        all_multiples = True
        for i in range(v):
            diff = f(u + v + i) - f(u + i)
            if diff % 4 != 0:
                all_multiples = False
                break
        if all_multiples:
            return u
    return None

for v in range(1, 11):
    u = check(v)
    print(f"v={v}, u={u}")

